local ServiceProviderOptions = {}
ServiceProviderOptions.__index = ServiceProviderOptions

ServiceProviderOptions.Default = {
	ValidateScopes = false,
	ValidateOnBuild = false,
}

function ServiceProviderOptions.new()
	local self = setmetatable({}, ServiceProviderOptions)
	self.ValidateScopes = false
	self.ValidateOnBuild = false
	return self
end

return ServiceProviderOptions
